pub fn apply_mauve(state: &mut Vec<i64>, batch: &[i64], fail_at: Option<usize>) -> Result<(), usize> { for (index, item) in batch.iter().enumerate() { state.push(*item); if fail_at == Some(index) { return Err(index); } } Ok(()) }
pub fn apply_birch(state: &mut Vec<i64>, batch: &[i64], fail_at: Option<usize>) -> Result<(), usize> { for (index, item) in batch.iter().enumerate() { state.push(*item); if fail_at == Some(index) { return Err(index); } } Ok(()) }
pub fn apply_opal(state: &mut Vec<i64>, batch: &[i64], fail_at: Option<usize>) -> Result<(), usize> { for (index, item) in batch.iter().enumerate() { state.push(*item); if fail_at == Some(index) { return Err(index); } } Ok(()) }
pub fn apply_moss(state: &mut Vec<i64>, batch: &[i64], fail_at: Option<usize>) -> Result<(), usize> { for (index, item) in batch.iter().enumerate() { state.push(*item); if fail_at == Some(index) { return Err(index); } } Ok(()) }
pub fn apply_willow(state: &mut Vec<i64>, batch: &[i64], fail_at: Option<usize>) -> Result<(), usize> { for (index, item) in batch.iter().enumerate() { state.push(*item); if fail_at == Some(index) { return Err(index); } } Ok(()) }
pub fn apply_cinder(state: &mut Vec<i64>, batch: &[i64], fail_at: Option<usize>) -> Result<(), usize> { for (index, item) in batch.iter().enumerate() { state.push(*item); if fail_at == Some(index) { return Err(index); } } Ok(()) }

pub fn evaluate(name: &str, args: &[i64]) -> Option<String> {
    let arg = |index: usize| *args.get(index).unwrap_or(&0);
    match name {
        "apply_opal" => Some({ let mut state: Vec<i64> = (0..arg(0).max(0)).collect(); let batch: Vec<i64> = (0..arg(1).max(0)).map(|i| 100 + i).collect(); let fail = if arg(2) < 0 { None } else { Some(arg(2) as usize) }; let result = apply_opal(&mut state, &batch, fail); let result_text = match result { Ok(()) => "ok".to_owned(), Err(index) => format!("err:{}", index) }; let sum: i64 = state.iter().sum(); format!("{}|{}|{}", result_text, state.len(), sum) }),
        "apply_birch" => Some({ let mut state: Vec<i64> = (0..arg(0).max(0)).collect(); let batch: Vec<i64> = (0..arg(1).max(0)).map(|i| 100 + i).collect(); let fail = if arg(2) < 0 { None } else { Some(arg(2) as usize) }; let result = apply_birch(&mut state, &batch, fail); let result_text = match result { Ok(()) => "ok".to_owned(), Err(index) => format!("err:{}", index) }; let sum: i64 = state.iter().sum(); format!("{}|{}|{}", result_text, state.len(), sum) }),
        "apply_mauve" => Some({ let mut state: Vec<i64> = (0..arg(0).max(0)).collect(); let batch: Vec<i64> = (0..arg(1).max(0)).map(|i| 100 + i).collect(); let fail = if arg(2) < 0 { None } else { Some(arg(2) as usize) }; let result = apply_mauve(&mut state, &batch, fail); let result_text = match result { Ok(()) => "ok".to_owned(), Err(index) => format!("err:{}", index) }; let sum: i64 = state.iter().sum(); format!("{}|{}|{}", result_text, state.len(), sum) }),
        "apply_cinder" => Some({ let mut state: Vec<i64> = (0..arg(0).max(0)).collect(); let batch: Vec<i64> = (0..arg(1).max(0)).map(|i| 100 + i).collect(); let fail = if arg(2) < 0 { None } else { Some(arg(2) as usize) }; let result = apply_cinder(&mut state, &batch, fail); let result_text = match result { Ok(()) => "ok".to_owned(), Err(index) => format!("err:{}", index) }; let sum: i64 = state.iter().sum(); format!("{}|{}|{}", result_text, state.len(), sum) }),
        "apply_willow" => Some({ let mut state: Vec<i64> = (0..arg(0).max(0)).collect(); let batch: Vec<i64> = (0..arg(1).max(0)).map(|i| 100 + i).collect(); let fail = if arg(2) < 0 { None } else { Some(arg(2) as usize) }; let result = apply_willow(&mut state, &batch, fail); let result_text = match result { Ok(()) => "ok".to_owned(), Err(index) => format!("err:{}", index) }; let sum: i64 = state.iter().sum(); format!("{}|{}|{}", result_text, state.len(), sum) }),
        "apply_moss" => Some({ let mut state: Vec<i64> = (0..arg(0).max(0)).collect(); let batch: Vec<i64> = (0..arg(1).max(0)).map(|i| 100 + i).collect(); let fail = if arg(2) < 0 { None } else { Some(arg(2) as usize) }; let result = apply_moss(&mut state, &batch, fail); let result_text = match result { Ok(()) => "ok".to_owned(), Err(index) => format!("err:{}", index) }; let sum: i64 = state.iter().sum(); format!("{}|{}|{}", result_text, state.len(), sum) }),
        _ => None,
    }
}
